// Modifications: rewritten in Rust for hodow_cts. The source texture tables are generated by scripts/gen_khr_get_texture_sub_image_tables.py into tables.rs. Upstream's `throw 0` is a `TestError::Fail`; `clean` is the `Drop` of the texture holders.

use std::ffi::c_void;

use crate::glu::{self, Context, TestCase, TestCaseGroup};
use crate::glw::{self, GLenum, GLint, GLsizei, GLuint};
use crate::tcu::{TestError, TestOutcome, TestStatus};

mod tables;

use tables::{
    ERRORS_TEXTURE_DATA, ERRORS_TEXTURE_DATA_COMPRESSED, FUNCTIONAL_TEXTURE_DATA, FUNCTIONAL_TEXTURE_DATA_COMPRESSED,
};

/// One GL call followed by upstream's `GLU_EXPECT_NO_ERROR` on it.
macro_rules! gl_call {
    ($gl:expr, $name:expr, $call:expr) => {{
        // SAFETY: every call below is made with a current context and with pointers into live buffers of the stated size.
        unsafe { $call };
        glu::expect_no_error($gl, $name)?;
    }};
}

fn supported(context: &Context) -> bool {
    context.context_type().supports_core(4, 5)
        || context
            .context_info
            .is_extension_supported("GL_ARB_get_texture_sub_image")
}

fn delete_texture(gl: &glw::Functions, texture: &mut GLuint) {
    if *texture != 0 {
        // SAFETY: deleting a texture name this test generated.
        unsafe { gl.delete_textures(1, &*texture) };
        *texture = 0;
    }
}

const ERRORS_TEXTURE_DATA_WIDTH: GLsizei = 2;
const ERRORS_TEXTURE_DATA_HEIGHT: GLsizei = 2;
const ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH: GLsizei = 4;
const ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT: GLsizei = 4;
const ERRORS_DESTINATION_BUFFER_SIZE: usize = if ERRORS_TEXTURE_DATA.len() > ERRORS_TEXTURE_DATA_COMPRESSED.len() {
    ERRORS_TEXTURE_DATA.len()
} else {
    ERRORS_TEXTURE_DATA_COMPRESSED.len()
};

/// `GetTextureSubImage::Errors`: the textures and the destination buffer made by `prepare`; `clean` is the `Drop`.
struct ErrorsState<'gl> {
    gl: &'gl glw::Functions,
    texture_1d: GLuint,
    texture_1d_array: GLuint,
    texture_2d: GLuint,
    texture_rectangle: GLuint,
    texture_2d_compressed: GLuint,
    texture_2d_multisampled: GLuint,
    destination_buffer: Vec<u8>,
}

impl Drop for ErrorsState<'_> {
    fn drop(&mut self) {
        let gl = self.gl;
        delete_texture(gl, &mut self.texture_1d);
        delete_texture(gl, &mut self.texture_1d_array);
        delete_texture(gl, &mut self.texture_2d);
        delete_texture(gl, &mut self.texture_rectangle);
        delete_texture(gl, &mut self.texture_2d_compressed);
        delete_texture(gl, &mut self.texture_2d_multisampled);
    }
}

impl<'gl> ErrorsState<'gl> {
    /// `Errors::prepare`
    fn prepare(gl: &'gl glw::Functions) -> Result<Self, TestError> {
        let mut state = ErrorsState {
            gl,
            texture_1d: 0,
            texture_1d_array: 0,
            texture_2d: 0,
            texture_rectangle: 0,
            texture_2d_compressed: 0,
            texture_2d_multisampled: 0,
            destination_buffer: Vec::new(),
        };

        gl_call!(
            gl,
            "glGenTextures call failed.",
            gl.gen_textures(1, &mut state.texture_1d)
        );
        gl_call!(
            gl,
            "glGenTextures call failed.",
            gl.gen_textures(1, &mut state.texture_1d_array)
        );
        gl_call!(
            gl,
            "glGenTextures call failed.",
            gl.gen_textures(1, &mut state.texture_2d)
        );
        gl_call!(
            gl,
            "glGenTextures call failed.",
            gl.gen_textures(1, &mut state.texture_rectangle)
        );
        gl_call!(
            gl,
            "glGenTextures call failed.",
            gl.gen_textures(1, &mut state.texture_2d_compressed)
        );
        gl_call!(
            gl,
            "glGenTextures call failed.",
            gl.gen_textures(1, &mut state.texture_2d_multisampled)
        );

        if state.texture_1d == 0 || state.texture_1d_array == 0 || state.texture_2d == 0 {
            return Err(TestError::Fail("texture names were not generated".to_string()));
        }

        let data = ERRORS_TEXTURE_DATA.as_ptr().cast::<c_void>();
        let (w, h) = (ERRORS_TEXTURE_DATA_WIDTH, ERRORS_TEXTURE_DATA_HEIGHT);

        gl_call!(
            gl,
            "glBindTexture call failed.",
            gl.bind_texture(glw::GL_TEXTURE_1D, state.texture_1d)
        );
        gl_call!(
            gl,
            "glTexImage1D call failed.",
            gl.tex_image_1d(
                glw::GL_TEXTURE_1D,
                0,
                glw::GL_RGBA8 as GLint,
                w,
                0,
                glw::GL_RGBA,
                glw::GL_UNSIGNED_BYTE,
                data
            )
        );

        gl_call!(
            gl,
            "glBindTexture call failed.",
            gl.bind_texture(glw::GL_TEXTURE_1D_ARRAY, state.texture_1d_array)
        );
        gl_call!(
            gl,
            "glTexImage1D call failed.",
            gl.tex_image_2d(
                glw::GL_TEXTURE_1D_ARRAY,
                0,
                glw::GL_RGBA8 as GLint,
                w,
                h,
                0,
                glw::GL_RGBA,
                glw::GL_UNSIGNED_BYTE,
                data
            )
        );

        gl_call!(
            gl,
            "glBindTexture call failed.",
            gl.bind_texture(glw::GL_TEXTURE_2D, state.texture_2d)
        );
        gl_call!(
            gl,
            "glTexImage1D call failed.",
            gl.tex_image_2d(
                glw::GL_TEXTURE_2D,
                0,
                glw::GL_RGBA8 as GLint,
                w,
                h,
                0,
                glw::GL_RGBA,
                glw::GL_UNSIGNED_BYTE,
                data
            )
        );

        gl_call!(
            gl,
            "glBindTexture call failed.",
            gl.bind_texture(glw::GL_TEXTURE_RECTANGLE, state.texture_rectangle)
        );
        gl_call!(
            gl,
            "glTexImage1D call failed.",
            gl.tex_image_2d(
                glw::GL_TEXTURE_RECTANGLE,
                0,
                glw::GL_RGBA8 as GLint,
                w,
                h,
                0,
                glw::GL_RGBA,
                glw::GL_UNSIGNED_BYTE,
                data
            )
        );

        gl_call!(
            gl,
            "glBindTexture call failed.",
            gl.bind_texture(glw::GL_TEXTURE_2D, state.texture_2d_compressed)
        );
        gl_call!(
            gl,
            "glTexImage1D call failed.",
            gl.compressed_tex_image_2d(
                glw::GL_TEXTURE_2D,
                0,
                glw::GL_COMPRESSED_RGB8_ETC2,
                ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH,
                ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT,
                0,
                ERRORS_TEXTURE_DATA_COMPRESSED.len() as GLsizei,
                ERRORS_TEXTURE_DATA_COMPRESSED.as_ptr().cast()
            )
        );

        gl_call!(
            gl,
            "glBindTexture call failed.",
            gl.bind_texture(glw::GL_TEXTURE_2D_MULTISAMPLE, state.texture_2d_multisampled)
        );
        gl_call!(
            gl,
            "glTexImage1D call failed.",
            gl.tex_image_2d_multisample(
                glw::GL_TEXTURE_2D_MULTISAMPLE,
                1,
                glw::GL_R8,
                w,
                h,
                glw::GL_TRUE as glw::GLboolean
            )
        );

        if gl.get_texture_sub_image.is_none() || gl.get_compressed_texture_sub_image.is_none() {
            return Err(TestError::Fail(
                "glGetTextureSubImage entry points are missing".to_string(),
            ));
        }

        state.destination_buffer = vec![0u8; ERRORS_DESTINATION_BUFFER_SIZE];
        Ok(state)
    }

    #[allow(clippy::too_many_arguments)]
    fn get_texture_sub_image(&mut self, texture: GLuint, offset: [GLint; 3], size: [GLsizei; 3], buf_size: GLsizei) {
        // SAFETY: the destination buffer is ERRORS_DESTINATION_BUFFER_SIZE bytes; the entry point is known to exist and the test expects it to reject any call it cannot satisfy.
        unsafe {
            self.gl.get_texture_sub_image(
                texture,
                0,
                offset[0],
                offset[1],
                offset[2],
                size[0],
                size[1],
                size[2],
                glw::GL_RGBA,
                glw::GL_UNSIGNED_BYTE,
                buf_size,
                self.destination_buffer.as_mut_ptr().cast(),
            )
        };
    }

    fn get_compressed_texture_sub_image(
        &mut self,
        texture: GLuint,
        offset: [GLint; 3],
        size: [GLsizei; 3],
        buf_size: GLsizei,
    ) {
        // SAFETY: as in get_texture_sub_image.
        unsafe {
            self.gl.get_compressed_texture_sub_image(
                texture,
                0,
                offset[0],
                offset[1],
                offset[2],
                size[0],
                size[1],
                size[2],
                buf_size,
                self.destination_buffer.as_mut_ptr().cast(),
            )
        };
    }

    /// The `glGetError` + message + comparison every `test*Error` repeats.
    fn expect_error(&self, expected: GLenum, message: &str) -> bool {
        // SAFETY: plain error query with a current context.
        let error_value = unsafe { self.gl.get_error() };
        let is_proper_error = error_value == expected;

        if !is_proper_error {
            log::info!(
                "{message} However, the error value {} was generated.",
                glw::error_name(error_value)
            );
        }
        is_proper_error
    }

    /// `Errors::testExistingTextureObjectError`
    fn test_existing_texture_object_error(&mut self) -> bool {
        let mut invalid_texture = self.texture_2d_multisampled;
        loop {
            invalid_texture += 1;
            // SAFETY: plain query with a current context.
            if unsafe { self.gl.is_texture(invalid_texture) } == 0 {
                break;
            }
        }

        let size = [ERRORS_TEXTURE_DATA_WIDTH, ERRORS_TEXTURE_DATA_HEIGHT, 1];
        self.get_texture_sub_image(
            invalid_texture,
            [0, 0, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let is_proper_error = self.expect_error(
            glw::GL_INVALID_OPERATION,
            "GL_INVALID_OPERATION error is expected to be generated by glGetTextureSubImage if texture is not the name of an existing texture object (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        let size = [
            ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH,
            ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT,
            1,
        ];
        self.get_compressed_texture_sub_image(
            invalid_texture,
            [0, 0, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let is_proper_error_compressed = self.expect_error(
            glw::GL_INVALID_OPERATION,
            "GL_INVALID_OPERATION error is expected to be generated by glGetCompressedTextureSubImage if texture is not the name of an existing texture object (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        is_proper_error && is_proper_error_compressed
    }

    /// `Errors::testBufferOrMultisampledTargetError`
    fn test_buffer_or_multisampled_target_error(&mut self) -> bool {
        let size = [ERRORS_TEXTURE_DATA_WIDTH, ERRORS_TEXTURE_DATA_HEIGHT, 1];
        self.get_texture_sub_image(
            self.texture_2d_multisampled,
            [0, 0, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );

        self.expect_error(
            glw::GL_INVALID_OPERATION,
            "GL_INVALID_OPERATION error is expected to be generated by glGetTextureSubImage if texture is the name of multisample texture (OpenGL 4.5 Core Specification chapter 8.11.4).",
        )
    }

    /// `Errors::testNegativeOffsetError`
    fn test_negative_offset_error(&mut self) -> bool {
        let size = [ERRORS_TEXTURE_DATA_WIDTH, ERRORS_TEXTURE_DATA_HEIGHT, 1];
        self.get_texture_sub_image(
            self.texture_2d,
            [-1, 0, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let is_proper_error = self.expect_error(
            glw::GL_INVALID_VALUE,
            "GL_INVALID_VALUE error is expected to be generated by glGetTextureSubImage if xoffset, yoffset or zoffset are negative (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        let size = [
            ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH,
            ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT,
            1,
        ];
        self.get_compressed_texture_sub_image(
            self.texture_2d_compressed,
            [-1, 0, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let is_proper_error_compressed = self.expect_error(
            glw::GL_INVALID_VALUE,
            "GL_INVALID_VALUE error is expected to be generated by glGetCompressedTextureSubImage if xoffset, yoffset or zoffset are negative (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        is_proper_error && is_proper_error_compressed
    }

    /// `Errors::testBoundsError`
    fn test_bounds_error(&mut self) -> bool {
        let size = [ERRORS_TEXTURE_DATA_WIDTH * 2, ERRORS_TEXTURE_DATA_HEIGHT * 2, 1];
        self.get_texture_sub_image(
            self.texture_2d,
            [ERRORS_TEXTURE_DATA_WIDTH, ERRORS_TEXTURE_DATA_HEIGHT, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let is_proper_error = self.expect_error(
            glw::GL_INVALID_VALUE,
            "GL_INVALID_VALUE error is expected to be generated by glGetTextureSubImage if xoffset + width is greater than the texture's width, yoffset + height is greater than the texture's height, or zoffset + depth is greater than the texture's depth. (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        let size = [
            ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH * 2,
            ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT * 2,
            1,
        ];
        self.get_compressed_texture_sub_image(
            self.texture_2d_compressed,
            [
                ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH,
                ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT,
                0,
            ],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let is_proper_error_compressed = self.expect_error(
            glw::GL_INVALID_VALUE,
            "GL_INVALID_VALUE error is expected to be generated by glGetCompressedTextureSubImage if xoffset + width is greater than the texture's width, yoffset + height is greater than the texture's height, or zoffset + depth is greater than the texture's depth. (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        is_proper_error && is_proper_error_compressed
    }

    /// `Errors::testOneDimmensionalTextureErrors`
    fn test_one_dimmensional_texture_errors(&mut self) -> bool {
        let size = [ERRORS_TEXTURE_DATA_WIDTH, 2, 1];
        self.get_texture_sub_image(
            self.texture_1d,
            [0, 1, 0],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );

        self.expect_error(
            glw::GL_INVALID_VALUE,
            "GL_INVALID_VALUE error is expected to be generated by glGetTextureSubImage if the effective target is GL_TEXTURE_1D and either yoffset is not zero, or height is not one (OpenGL 4.5 Core Specification chapter 8.11.4).",
        )
    }

    /// `Errors::testTwoDimmensionalTextureErrors`
    fn test_two_dimmensional_texture_errors(&mut self) -> bool {
        let test_textures = [
            (self.texture_1d, "GL_TEXTURE_1D"),
            (self.texture_1d_array, "GL_TEXTURE_1D_ARRAY"),
            (self.texture_2d, "GL_TEXTURE_2D"),
        ];

        let mut is_error = true;

        for (id, target_name) in test_textures {
            let height = if id == self.texture_1d {
                1
            } else {
                ERRORS_TEXTURE_DATA_HEIGHT
            };
            self.get_texture_sub_image(
                id,
                [0, 0, 1],
                [ERRORS_TEXTURE_DATA_WIDTH, height, 2],
                ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
            );

            let message = format!(
                "GL_INVALID_VALUE error is expected to be generated by glGetTextureSubImage if the effective target is {target_name} and either zoffset is not zero, or depth is not one. (OpenGL 4.5 Core Specification chapter 8.11.4)."
            );
            if !self.expect_error(glw::GL_INVALID_VALUE, &message) {
                is_error = false;
            }
        }

        let size = [
            ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH,
            ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT,
            2,
        ];
        self.get_compressed_texture_sub_image(
            self.texture_2d_compressed,
            [0, 0, 1],
            size,
            ERRORS_DESTINATION_BUFFER_SIZE as GLsizei,
        );
        let message = "GL_INVALID_VALUE error is expected to be generated by glGetCompressedTextureSubImage if the effective target is GL_TEXTURE_2D and either zoffset is not zero, or depth is not one. (OpenGL 4.5 Core Specification chapter 8.11.4).";
        if !self.expect_error(glw::GL_INVALID_VALUE, message) {
            is_error = false;
        }

        is_error
    }

    /// `Errors::testBufferSizeError`
    fn test_buffer_size_error(&mut self) -> bool {
        let size = [ERRORS_TEXTURE_DATA_WIDTH, ERRORS_TEXTURE_DATA_HEIGHT, 1];
        self.get_texture_sub_image(self.texture_2d, [0, 0, 0], size, 1);
        let is_proper_error = self.expect_error(
            glw::GL_INVALID_OPERATION,
            "GL_INVALID_OPERATION error is expected to be generated by glGetTextureSubImage if the buffer size required to store the requested data is greater than bufSize. (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        let size = [
            ERRORS_TEXTURE_DATA_COMPRESSED_WIDTH,
            ERRORS_TEXTURE_DATA_COMPRESSED_HEIGHT,
            1,
        ];
        self.get_compressed_texture_sub_image(self.texture_2d_compressed, [0, 0, 0], size, 1);
        let is_proper_error_compressed = self.expect_error(
            glw::GL_INVALID_OPERATION,
            "GL_INVALID_OPERATION error is expected to be generated by glGetCompressedTextureSubImage if the buffer size required to store the requested data is greater than bufSize. (OpenGL 4.5 Core Specification chapter 8.11.4).",
        );

        is_proper_error && is_proper_error_compressed
    }
}

/// `GetTextureSubImage::Errors`
struct Errors;

impl TestCase for Errors {
    fn name(&self) -> &str {
        "errors_test"
    }

    fn iterate(&self, context: &Context) -> TestOutcome {
        let gl = context.gl();
        let mut is_ok = true;

        if supported(context) {
            let mut state = ErrorsState::prepare(gl)?;

            is_ok &= state.test_existing_texture_object_error();
            is_ok &= state.test_buffer_or_multisampled_target_error();
            is_ok &= state.test_negative_offset_error();
            is_ok &= state.test_bounds_error();
            is_ok &= state.test_one_dimmensional_texture_errors();
            is_ok &= state.test_two_dimmensional_texture_errors();
            is_ok &= state.test_buffer_size_error();
        }

        Ok(if is_ok {
            TestStatus::pass("Pass")
        } else {
            TestStatus::fail("Fail")
        })
    }
}

const FUNCTIONAL_TEXTURE_DATA_WIDTH: GLsizei = 8;
const FUNCTIONAL_TEXTURE_DATA_HEIGHT: GLsizei = 8;
const FUNCTIONAL_TEXTURE_DATA_DEPTH: GLsizei = 8;
const FUNCTIONAL_TEXTURE_DATA_COMPRESSED_SIZE: GLsizei = FUNCTIONAL_TEXTURE_DATA_COMPRESSED.len() as GLsizei;

/// `GetTextureSubImage::Functional::prepare`
fn functional_prepare(
    gl: &glw::Functions,
    texture: &mut GLuint,
    target: GLenum,
    is_compressed: bool,
) -> Result<(), TestError> {
    const FACES: [GLenum; 6] = [
        glw::GL_TEXTURE_CUBE_MAP_POSITIVE_X,
        glw::GL_TEXTURE_CUBE_MAP_NEGATIVE_X,
        glw::GL_TEXTURE_CUBE_MAP_POSITIVE_Y,
        glw::GL_TEXTURE_CUBE_MAP_NEGATIVE_Y,
        glw::GL_TEXTURE_CUBE_MAP_POSITIVE_Z,
        glw::GL_TEXTURE_CUBE_MAP_NEGATIVE_Z,
    ];
    let (w, h, d) = (
        FUNCTIONAL_TEXTURE_DATA_WIDTH,
        FUNCTIONAL_TEXTURE_DATA_HEIGHT,
        FUNCTIONAL_TEXTURE_DATA_DEPTH,
    );

    gl_call!(gl, "glGenTextures call failed.", gl.gen_textures(1, texture));
    gl_call!(gl, "glBindTexture call failed.", gl.bind_texture(target, *texture));

    if is_compressed {
        let layer_size = FUNCTIONAL_TEXTURE_DATA_COMPRESSED_SIZE / d;
        let data = FUNCTIONAL_TEXTURE_DATA_COMPRESSED.as_ptr();
        let bptc = glw::GL_COMPRESSED_RGBA_BPTC_UNORM;

        match target {
            glw::GL_TEXTURE_2D => {
                gl_call!(
                    gl,
                    "glCompressedTexImage2D call failed.",
                    gl.compressed_tex_image_2d(target, 0, bptc, w, h, 0, layer_size, data.cast())
                );
            }
            glw::GL_TEXTURE_CUBE_MAP => {
                for (face, face_target) in FACES.into_iter().enumerate() {
                    // SAFETY: each face reads layer_size bytes at a multiple of layer_size, inside the 8 layer table.
                    unsafe {
                        gl.compressed_tex_image_2d(
                            face_target,
                            0,
                            bptc,
                            w,
                            h,
                            0,
                            layer_size,
                            data.add(face * layer_size as usize).cast(),
                        )
                    };
                }
                glu::expect_no_error(gl, "glCompressedTexImage2D call failed.")?;
            }
            glw::GL_TEXTURE_CUBE_MAP_ARRAY => {
                gl_call!(
                    gl,
                    "glCompressedTexImage3D call failed.",
                    gl.compressed_tex_image_3d(target, 0, bptc, w, h, 6, 0, layer_size * 6, data.cast())
                );
            }
            glw::GL_TEXTURE_2D_ARRAY => {
                gl_call!(
                    gl,
                    "glCompressedTexImage3D call failed.",
                    gl.compressed_tex_image_3d(
                        target,
                        0,
                        bptc,
                        w,
                        h,
                        d,
                        0,
                        FUNCTIONAL_TEXTURE_DATA_COMPRESSED_SIZE,
                        data.cast()
                    )
                );
            }
            _ => return Err(TestError::Fail("unsupported target".to_string())),
        }
    } else {
        let data = FUNCTIONAL_TEXTURE_DATA.as_ptr();
        let rgba8 = glw::GL_RGBA8 as GLint;
        let (rgba, ubyte) = (glw::GL_RGBA, glw::GL_UNSIGNED_BYTE);

        match target {
            glw::GL_TEXTURE_1D => {
                gl_call!(
                    gl,
                    "glTexImage1D call failed.",
                    gl.tex_image_1d(target, 0, rgba8, w, 0, rgba, ubyte, data.cast())
                );
            }
            glw::GL_TEXTURE_1D_ARRAY | glw::GL_TEXTURE_2D | glw::GL_TEXTURE_RECTANGLE => {
                gl_call!(
                    gl,
                    "glTexImage2D call failed.",
                    gl.tex_image_2d(target, 0, rgba8, w, h, 0, rgba, ubyte, data.cast())
                );
            }
            glw::GL_TEXTURE_CUBE_MAP => {
                for (face, face_target) in FACES.into_iter().enumerate() {
                    // SAFETY: each face reads w * h * 4 bytes at a multiple of that, inside the 8 layer table.
                    unsafe {
                        gl.tex_image_2d(
                            face_target,
                            0,
                            rgba8,
                            w,
                            h,
                            0,
                            rgba,
                            ubyte,
                            data.add(face * (w * h * 4) as usize).cast(),
                        )
                    };
                }
                glu::expect_no_error(gl, "glTexImage2D call failed.")?;
            }
            glw::GL_TEXTURE_CUBE_MAP_ARRAY => {
                gl_call!(
                    gl,
                    "glTexImage3D call failed.",
                    gl.tex_image_3d(target, 0, rgba8, w, h, 6, 0, rgba, ubyte, data.cast())
                );
            }
            glw::GL_TEXTURE_2D_ARRAY | glw::GL_TEXTURE_3D => {
                gl_call!(
                    gl,
                    "glTexImage3D call failed.",
                    gl.tex_image_3d(target, 0, rgba8, w, h, d, 0, rgba, ubyte, data.cast())
                );
            }
            _ => return Err(TestError::Fail("unsupported target".to_string())),
        }
    }
    Ok(())
}

/// `GetTextureSubImage::Functional::check`
fn functional_check(
    gl: &glw::Functions,
    texture: GLuint,
    target: GLenum,
    is_compressed: bool,
) -> Result<bool, TestError> {
    let (data_w, data_h, data_d) = (
        FUNCTIONAL_TEXTURE_DATA_WIDTH,
        FUNCTIONAL_TEXTURE_DATA_HEIGHT,
        FUNCTIONAL_TEXTURE_DATA_DEPTH,
    );

    let x_offset = data_w / 2;
    let width = data_w / 2;

    let mut y_offset = 0;
    let mut height = 1;

    let mut z_offset = 0;
    let mut depth = 1;

    if target != glw::GL_TEXTURE_1D {
        y_offset = data_h / 2;
        height = data_h / 2;
    }

    if target == glw::GL_TEXTURE_3D || target == glw::GL_TEXTURE_2D_ARRAY {
        z_offset = data_d / 2;
        depth = data_d / 2;
    }

    if target == glw::GL_TEXTURE_CUBE_MAP || target == glw::GL_TEXTURE_CUBE_MAP_ARRAY {
        z_offset = 3;
        depth = 3;
    }

    let number_of_components: GLint = if is_compressed { 16 } else { 4 };

    let (mut x_block, mut y_block): (GLint, GLint) = (1, 1);

    let size: GLsizei = if is_compressed {
        x_block = 4;
        y_block = 4;
        (width / x_block) * (height / y_block) * depth * number_of_components
    } else {
        width * height * depth * number_of_components
    };

    let mut texture_data = vec![0u8; size as usize];

    // SAFETY: texture_data holds `size` bytes, the buffer size passed to the call.
    unsafe {
        if is_compressed {
            gl.get_compressed_texture_sub_image(
                texture,
                0,
                x_offset,
                y_offset,
                z_offset,
                width,
                height,
                depth,
                size,
                texture_data.as_mut_ptr().cast(),
            );
        } else {
            gl.get_texture_sub_image(
                texture,
                0,
                x_offset,
                y_offset,
                z_offset,
                width,
                height,
                depth,
                glw::GL_RGBA,
                glw::GL_UNSIGNED_BYTE,
                size,
                texture_data.as_mut_ptr().cast(),
            );
        }
    }

    // SAFETY: plain error query with a current context.
    let error = unsafe { gl.get_error() };

    if error != glw::GL_NO_ERROR {
        return Err(TestError::Fail(format!("GL error {}", glw::error_name(error))));
    }

    let reference: &[u8] = if is_compressed {
        &FUNCTIONAL_TEXTURE_DATA_COMPRESSED
    } else {
        &FUNCTIONAL_TEXTURE_DATA
    };
    let mut is_ok = true;

    for k in 0..depth {
        for j in 0..height / y_block {
            for i in 0..width / x_block {
                for c in 0..number_of_components {
                    let reference_data_position = (i + (x_offset / x_block)) * number_of_components
                        + (j + (y_offset / y_block)) * data_w / x_block * number_of_components
                        + (k + z_offset) * data_w / x_block * data_h / y_block * number_of_components
                        + c;

                    let tested_data_position = i * number_of_components
                        + j * width / x_block * number_of_components
                        + k * width / x_block * height / y_block * number_of_components
                        + c;

                    let reference_value = reference[reference_data_position as usize];
                    let tested_value = texture_data[tested_data_position as usize];

                    if reference_value != tested_value {
                        is_ok = false;
                        break;
                    }
                }
            }
        }
    }

    if !is_ok {
        log::info!(
            "Functional test of {} function has failed with target {target:#x}.",
            if is_compressed {
                "glGetCompressedTextureSubImage "
            } else {
                "glGetTextureSubImage "
            }
        );
    }

    Ok(is_ok)
}

/// `GetTextureSubImage::Functional`
struct Functional;

impl Functional {
    fn run(gl: &glw::Functions, texture: &mut GLuint) -> Result<bool, TestError> {
        if gl.get_compressed_texture_sub_image.is_none() || gl.get_texture_sub_image.is_none() {
            log::info!("Cannot obtain glGetCompressedTextureSubImage or glGetTextureSubImage function pointer.");
            return Err(TestError::Fail("missing entry points".to_string()));
        }

        let mut is_ok = true;

        for target in [
            glw::GL_TEXTURE_1D,
            glw::GL_TEXTURE_1D_ARRAY,
            glw::GL_TEXTURE_2D,
            glw::GL_TEXTURE_RECTANGLE,
            glw::GL_TEXTURE_CUBE_MAP,
            glw::GL_TEXTURE_CUBE_MAP_ARRAY,
            glw::GL_TEXTURE_2D_ARRAY,
            glw::GL_TEXTURE_3D,
        ] {
            functional_prepare(gl, texture, target, false)?;
            is_ok &= functional_check(gl, *texture, target, false)?;
            delete_texture(gl, texture);
        }

        for target in [
            glw::GL_TEXTURE_2D,
            glw::GL_TEXTURE_CUBE_MAP,
            glw::GL_TEXTURE_CUBE_MAP_ARRAY,
            glw::GL_TEXTURE_2D_ARRAY,
        ] {
            functional_prepare(gl, texture, target, true)?;
            is_ok &= functional_check(gl, *texture, target, true)?;
            delete_texture(gl, texture);
        }

        Ok(is_ok)
    }
}

impl TestCase for Functional {
    fn name(&self) -> &str {
        "functional_test"
    }

    fn iterate(&self, context: &Context) -> TestOutcome {
        let gl = context.gl();
        let mut texture: GLuint = 0;

        let result = if supported(context) {
            Self::run(gl, &mut texture)
        } else {
            Ok(true)
        };
        delete_texture(gl, &mut texture);

        Ok(if result? {
            TestStatus::pass("Pass")
        } else {
            TestStatus::fail("Fail")
        })
    }
}

/// `GetTextureSubImage::Tests`
pub fn create_tests() -> TestCaseGroup {
    let mut group = TestCaseGroup::new("get_texture_sub_image");
    group.add_child(Box::new(Errors) as Box<dyn TestCase>);
    group.add_child(Box::new(Functional) as Box<dyn TestCase>);
    group
}
